311			t.Fatalf("stderr must name the smallest offending cluster c-b, got %q", stderr)
312		}
313		if !strings.Contains(stderr, "zone") {
314			t.Fatalf("stderr must name the missing tag zone, got %q", stderr)
315		}
316		if strings.Contains(stderr, "c-c") {
317			t.Fatalf("with multiple offenders stderr must point at the smallest c-b, got %q", stderr)
318		}
319	}
320	
321	// TestPlanCLI_SpreadByEmptyTagValueIsDomain verifies through the CLI that a
322	// tag present with an empty string value is a legal fault domain, distinct
323	// from a missing tag: empty-valued clusters avoid each other but still share
324	// batches with other domains.
325	func TestPlanCLI_SpreadByEmptyTagValueIsDomain(t *testing.T) {
326		doc := `{
327	  "app": "app", "revision": "r1", "image": "img",
328	  "batchSize": 2, "spreadBy": "zone",
329	  "clusters": [
330	    {"id": "c", "tags": {"zone": "east"}},
331	    {"id": "a", "tags": {"zone": ""}},
332	    {"id": "b", "tags": {"zone": ""}}
333	  ]
334	}`
335		code, stdout, stderr := runCLI(t, "plan", writePlanDoc(t, doc))
336		if code != 0 {
337			t.Fatalf("expected exit 0, got %d; stderr=%q", code, stderr)
338		}
339		if stderr != "" {
340			t.Fatalf("unexpected stderr: %q", stderr)
341		}
342		p := decodeCLIPlan(t, stdout)
343		domains := map[string]string{"a": "", "b": "", "c": "east"}
344		// a and b share the empty domain and must not share a batch; c fills batch 1.
345		assertSpreadBatches(t, p, [][]string{{"a", "c"}, {"b"}}, domains, 2)
346	}
347	
348	// TestPlanCLI_NoSpreadByKeepsLegacyBatching verifies that omitting spreadBy
349	// or setting it to "" preserves the original behavior at the CLI level:
350	// ascending IDs split purely by capacity, so clusters of the same domain may
351	// share a batch. Both spellings must produce identical output.
352	func TestPlanCLI_NoSpreadByKeepsLegacyBatching(t *testing.T) {
353		docs := map[string]string{
354			"absent": `{
355	  "app": "app", "revision": "r1", "image": "img",
356	  "batchSize": 2,
357	  "clusters": [
358	    {"id": "c3"},
359	    {"id": "c1", "tags": {"zone": "east"}},
360	    {"id": "c2", "tags": {"zone": "east"}}
361	  ]
362	}`,
363			"empty": `{
364	  "app": "app", "revision": "r1", "image": "img",
365	  "batchSize": 2, "spreadBy": "",
366	  "clusters": [
367	    {"id": "c2", "tags": {"zone": "east"}},
368	    {"id": "c3"},
369	    {"id": "c1", "tags": {"zone": "east"}}
370	  ]
371	}`,
372		}
373		outputs := map[string]string{}
374		for name, doc := range docs {
375			code, stdout, stderr := runCLI(t, "plan", writePlanDoc(t, doc))
376			if code != 0 {
377				t.Fatalf("%s: expected exit 0, got %d; stderr=%q", name, code, stderr)
378			}
379			if stderr != "" {
380				t.Fatalf("%s: unexpected stderr: %q", name, stderr)
381			}
382			outputs[name] = strings.TrimSpace(stdout)
383		}
384		if outputs["absent"] != outputs["empty"] {
385			t.Fatalf("absent and empty spreadBy differ:\n%s\n----\n%s", outputs["absent"], outputs["empty"])
386		}
387		p := decodeCLIPlan(t, outputs["absent"])
388		// Legacy packing ignores domains: the two same-domain clusters c1 and c2
389		// share batch 1, ordered ascending; c3 takes batch 2.
390		if len(p.Batches) != 2 {
391			t.Fatalf("expected 2 batches, got %+v", p.Batches)
392		}
393		if strings.Join(p.Batches[0].Clusters, ",") != "c1,c2" {
394			t.Fatalf("batch 1 = %v, want [c1 c2] (same domain may share a batch)", p.Batches[0].Clusters)
395		}
396		if p.Batches[0].Index != 1 || p.Batches[1].Index != 2 {
397			t.Fatalf("batch indices must run from 1 consecutively, got %d and %d", p.Batches[0].Index, p.Batches[1].Index)
398		}
399		if strings.Join(p.Batches[1].Clusters, ",") != "c3" {
400			t.Fatalf("batch 2 = %v, want [c3]", p.Batches[1].Clusters)
401		}
402	}
